  // src/lib/hsl-slider-track.js
  function schemeSliderHues(baseColorHex, scheme) {
    const { h: h3 } = hexToHsl(baseColorHex || "#8a8a8a");
    return [0, ...accentHueOffsets(scheme || "analog")].map(
      (offset) => (h3 + offset + 360) % 360
    );
  }
  function schemeHslTrackStyle(baseColorHex, scheme, channel) {
    const hsl = hexToHsl(baseColorHex || "#8a8a8a");
    const hues = schemeSliderHues(baseColorHex, scheme);
    const n4 = Math.max(hues.length, 1);
    const parts = [`--hsl-band-count:${n4}`];
    for (let i5 = 0; i5 < 4; i5++) {
      if (i5 < hues.length) {
        const h3 = hues[i5];
        if (channel === "s") {
          parts.push(`--hsl-band-${i5}-a:${hslToHex({ h: h3, s: 0, l: hsl.l })}`);
          parts.push(`--hsl-band-${i5}-b:${hslToHex({ h: h3, s: 100, l: hsl.l })}`);
        } else {
          parts.push(`--hsl-band-${i5}-a:${hslToHex({ h: h3, s: hsl.s, l: 8 })}`);
          parts.push(`--hsl-band-${i5}-b:${hslToHex({ h: h3, s: hsl.s, l: 92 })}`);
        }
      } else {
        parts.push(`--hsl-band-${i5}-a:transparent`);
        parts.push(`--hsl-band-${i5}-b:transparent`);
      }
    }
    return parts.join(";");
  }

  // src/popup/components/gmixer-color-wheel.js
